169→ */
170→export function isInitialized(): boolean {
171→	return initialized;
172→}
173→
174→/**
175→ * Clear invalid selection and prompt user to select valid project
176→ * AC: @multi-directory-daemon ac-36 - Invalid project recovery
177→ */
178→export function clearInvalidSelection(): void {
179→	selectedPath = null;
180→	persistSelection(null);
181→	error = 'Selected project is no longer valid. Please select a project.';
