 51→				ready: 0,
 52→				in_progress: 0,
 53→				pending_review: 0,
 54→				blocked: 0,
 55→				completed: 0
 56→			};
 57→
 58→			// Build a set of completed task refs for dependency checking
 59→			const completedRefs = new Set(
 60→				tasks
 61→					.filter((t) => t.status === 'completed')
 62→					.flatMap((t) => [t._ulid, ...(t.slugs || [])])
 63→			);
