 71→					newCounts.pending_review++;
 72→				} else if (task.status === 'blocked') {
 73→					newCounts.blocked++;
 74→				} else if (task.status === 'pending') {
 75→					// Check if blocked by dependencies
 76→					const deps = task.depends_on || [];
